select * from yh_user_heart_rate where E_User_Id=#{usercode} and Is_Del=2

  AND Entry_Time >=  #{strTime} AND Entry_Time <= #{endTime}


  AND Entry_Time LIKE CONCAT('',#{strTime},'%')


  AND YEAR(Entry_Time) =#{strTime}

SELECT COUNT(0) FROM (SELECT * FROM `yh_user_heart_rate` WHERE `E_User_Id`=#{usercode} AND Is_Del=2

  AND  Entry_Time >=  #{strTime} AND Entry_Time <= #{endTime}


  AND  Entry_Time LIKE CONCAT('',#{strTime},'%')


  AND YEAR(Entry_Time) =#{strTime}


LIMIT #{page}) AS a
WHERE 	   CAST(a.heart_rate AS DECIMAL(10,2)) < 60

 SELECT COUNT(0) FROM (SELECT * FROM `yh_user_heart_rate` WHERE `E_User_Id`=#{usercode} AND Is_Del=2

  AND  Entry_Time >=  #{strTime} AND Entry_Time <= #{endTime}


  AND  Entry_Time LIKE CONCAT('',#{strTime},'%')


  AND YEAR(Entry_Time) =#{strTime}


LIMIT #{page}
 ) AS a
WHERE 	   CAST(a.heart_rate AS DECIMAL(10,2)) >= 60 and  CAST(a.heart_rate AS DECIMAL(10,2)) <= 100

 SELECT COUNT(0) FROM (SELECT * FROM `yh_user_heart_rate` WHERE `E_User_Id`=#{usercode} AND Is_Del=2

  AND  Entry_Time >=  #{strTime} AND Entry_Time <= #{endTime}


  AND  Entry_Time LIKE CONCAT('',#{strTime},'%')


  AND YEAR(Entry_Time) =#{strTime}


